(7102831, 1082406, 12611, '<td valign="top">Top 3 for me.The smoothness gone, age shows the cracks- yet it continues, the real dance, the constant rhythm of life.</td>', 'Top 3 for me.The smoothness gone, age shows the cracks- yet it continues, the real dance, the constant rhythm of life.', '2013-09-14 21:57:25.000000', NULL, 1),
(7102834, 1082077, 12611, '<td valign="top">A top shot for me. I love the bold placement, the stubborn and defiant separation of the objects, all three, light dark and shadow, tied together by the concrete floor.</td>', 'A top shot for me. I love the bold placement, the stubborn and defiant separation of the objects, all three, light dark and shadow, tied together by the concrete floor.', '2013-09-14 21:59:04.000000', NULL, 1),
(7102837, 1082458, 12611, '<td valign="top">Great subtle shifts in the monotone. The imperfections make it.</td>', 'Great subtle shifts in the monotone. The imperfections make it.', '2013-09-14 22:01:03.000000', NULL, 1),
(7102838, 1082449, 12611, '<td valign="top">A freegan''s paradise, a long a stinky way to go to make a point. Kudos.</td>', 'A freegan''s paradise, a long a stinky way to go to make a point. Kudos.', '2013-09-14 22:01:51.000000', NULL, 1),
